# The nose of the owner's reference (royalthaiart.com, Thai Lanna dancing woman, 524; 1080 px), measured in the
# browser: every pixel along each painted line, looking across it, the line's centre, its width (px) and its peak
# darkness below the skin. Mapped here onto the mural head (mirrored, set by the irises) and written as JS data:
# [x, y, ink] in units, ink = the width of the line in units were it painted at full strength in its own colour.
import re

DATA = {
    "bridge": "558.4 247.1 1.9 18,558.5 248.1 2.1 31,558.7 249.1 1.9 40,558.9 250.0 1.9 38,559.2 251.0 1.8 40,559.3 252.0 1.8 41,559.3 253.0 1.7 48,559.3 254.0 1.9 42,559.3 255.0 1.9 39,559.2 255.3 1.9 36,559.2 256.4 1.6 38,559.1 257.4 1.5 41,559.0 258.4 1.7 39,558.7 259.3 1.9 32,558.4 260.3 2.1 26,558.0 261.2 1.9 29,557.9 261.6 1.9 28,557.6 262.5 2.2 23,557.1 263.4 2.1 24,556.6 264.3 2.2 25,556.2 265.2 1.9 29,555.7 266.1 2.0 27,555.2 266.9 1.8 23,554.6 267.7 2.0 22,554.0 268.6 2.0 27,553.5 269.4 2.2 25,553.0 270.2 2.0 25,552.4 271.0 2.1 25,552.0 271.9 1.9 25,551.3 272.7 1.9 21,550.7 273.4 2.0 22,550.2 274.3 1.9 24,549.6 275.1 2.0 21,549.0 275.9 1.7 20,548.3 276.6 1.8 17,547.7 277.4 1.9 17,547.4 277.9 1.8 17,546.7 278.7 1.8 18,546.2 279.6 2.0 23,545.7 280.4 2.2 24,545.2 281.3 2.0 19,544.6 282.1 2.1 18,544.2 283.0 2.1 19,543.8 284.0 2.0 18,543.4 284.9 2.1 16,542.9 285.8 2.1 21,542.6 286.4 2.3 24,542.4 287.4 2.1 29,542.0 288.3 2.1 46,541.8 289.3 2.3 67,541.7 290.3 2.4 82,541.6 290.7 2.4 83,541.8 291.8 2.4 85,542.0 292.7 2.3 81,542.4 293.6 2.6 71,543.0 294.5 2.4 74,543.4 294.9 2.3 75,544.2 295.6 2.3 75,545.1 296.0 2.5 75,546.0 296.4 2.6 77,546.9 296.9 2.3 69,547.8 297.3 2.5 51,548.6 297.8 2.4 57,549.3 298.6 2.5 65,550.0 299.3 2.6 73,550.6 300.3 3.0 68,550.9 301.0 2.5 61,551.2 302.0 2.5 53,551.3 303.0 2.6 48,551.1 304.1 2.8 40,550.9 305.2 3.1 29,550.6 306.3 2.9 25",
    "brow": "555.8 235.4 1.7 13,555.1 234.0 2.0 27,554.3 232.6 2.3 38,553.7 231.1 2.0 82,553.0 229.7 2.1 115,552.0 228.4 2.2 151,551.0 227.1 2.2 172,550.0 225.9 2.2 168,548.9 224.8 2.3 144,547.7 223.7 2.3 146,546.3 222.8 2.3 143,544.9 222.0 2.3 157,543.4 221.4 2.6 148,541.8 221.0 2.4 167,540.3 220.7 2.6 170,538.6 220.6 2.6 161,537.0 220.6 2.7 163,535.4 220.7 2.8 170,533.8 220.7 2.9 166,532.2 220.5 2.4 120,530.6 220.4 2.0 60",
    "nostril": "553.5 296.6 2.7 58,554.5 296.7 2.6 72,555.4 297.1 2.5 83,556.4 297.4 2.5 82,557.2 297.7 2.6 75,558.1 298.1 2.3 74,559.0 298.6 2.3 67,559.9 299.0 2.1 61",
    "wing": "563.1 288.1 2.0 5,564.3 287.8 2.2 5,565.4 287.7 2.1 9,566.4 287.9 1.8 12,567.2 288.7 2.1 17,568.0 289.7 1.8 19,568.5 290.5 2.2 19,569.0 291.4 1.8 21,569.3 292.4 2.0 21,569.5 293.5 2.5 22,569.6 293.8 2.3 22,569.6 294.9 2.2 24,569.6 295.9 2.2 26,569.6 296.9 2.4 22,569.4 297.9 2.3 20,568.8 298.4 2.5 18,568.2 299.4 2.2 13,567.4 300.0 1.9 15,566.3 300.1 2.1 17,565.5 300.4 2.2 18,564.5 300.5 2.3 19,563.5 300.4 2.1 21,562.5 300.1 2.0 27,561.5 299.5 2.6 32",
}
# each line's paint at full strength, its darkness below her skin (249, 250, 254) less the measuring threshold of 6:
# the nose's mauve (165, 149, 160) at the tip, the brow's (72, 70, 80)
FULL = {"bridge": 89.0, "nostril": 89.0, "wing": 89.0, "brow": 173.0}
src = [complex(-609, 261), complex(-543.5, 251)]     # her irises, near and far, mirrored
dst = [complex(-0.5, -51.2), complex(27.3, -52.2)]   # ours
a = (dst[1] - dst[0]) / (src[1] - src[0]); b = dst[0] - a * src[0]; k = abs(a)

out = []
for name, text in DATA.items():
    pts = []
    for item in text.split(","):
        x, y, w, peak = map(float, item.split())
        z = a * complex(-x, y) + b
        pts.append((z.real, z.imag, w * peak / FULL[name] * k))
    # the JPEG's noise out of the measurement: a running mean over five points (two pixels of the painting)
    sm = []
    for i in range(len(pts)):
        win = pts[max(0, i - 2):i + 3]
        sm.append("[%.2f,%.2f,%.3f]" % tuple(sum(q[j] for q in win) / len(win) for j in range(3)))
    out.append("  %s: [%s]" % (name, ",".join(sm)))
print("var NOSE_LANNA = {\n" + ",\n".join(out) + "\n};")
